import{_ as e,c as r,o as i,ah as t}from"./chunks/framework.CoJbR2uz.js";const _=JSON.parse('{"title":"隐私政策","description":"","frontmatter":{"outline":[2,3]},"headers":[],"relativePath":"privacy.md","filePath":"privacy.md"}'),o={name:"privacy.md"};function l(n,a,s,h,c,d){return i(),r("div",null,[...a[0]||(a[0]=[t('<h1 id="隐私政策" tabindex="-1">隐私政策 <a class="header-anchor" href="#隐私政策" aria-label="Permalink to “隐私政策”">​</a></h1><p><strong>生效日期：</strong> 2026 年 3 月 12 日<br><strong>最后更新日期：</strong> 2026 年 3 月 12 日</p><p>欢迎使用 Cylorine Studio（以下简称“我们”、“我们的”）提供的产品与服务。我们高度重视用户隐私保护，并承诺以清晰、透明的方式说明我们如何处理您的信息。请您在使用我们的产品与服务前，仔细阅读并充分理解本隐私政策的全部内容。</p><h2 id="_1-信息收集范围" tabindex="-1">1. 信息收集范围 <a class="header-anchor" href="#_1-信息收集范围" aria-label="Permalink to “1. 信息收集范围”">​</a></h2><p>我们遵循最小必要原则，<strong>不主动收集任何可直接识别个人身份的信息</strong>（如姓名、地址、电话号码等）。在您访问我们的官方网站或使用我们的软件（包括但不限于 PCL.Mac、Cylorine Launcher）时，以下技术信息可能被自动记录：</p><ul><li><strong>软件版本信息</strong>：当您的软件向我们的 API 发送请求时，请求中会包含软件名称及版本号（例如 <code>PCL-Mac/1.0.0</code>），用于识别软件版本以提供相应服务。<br>此外，为了统计各版本用户量、了解旧版本用户占比，我们的软件会每日一次（理想情况下）主动向我们的 API 上报当前版本号。此上报不包含任何个人身份信息，仅用于聚合统计。</li><li><strong>网络日志信息</strong>：包括 IP 地址及请求时间。此类信息是互联网通信的常规记录，仅用于保障服务安全与稳定运行，我们不会将 IP 地址用于定位或识别具体个人。</li><li><strong>网站访问信息</strong>：我们的官方网站托管于 <strong>GitHub Pages</strong> 平台。GitHub 可能自动收集标准的服务器访问日志（如浏览器类型、访问时间、来源页面等）。该等信息由 GitHub 按其隐私政策处理，我们无法直接访问或控制。详情请参阅 <a href="https://docs.github.com/en/site-policy/privacy-policies/github-privacy-statement" target="_blank" rel="noreferrer">GitHub 隐私声明</a>。</li></ul><h2 id="_2-信息使用目的" tabindex="-1">2. 信息使用目的 <a class="header-anchor" href="#_2-信息使用目的" aria-label="Permalink to “2. 信息使用目的”">​</a></h2><p>我们仅将收集的信息用于以下合法目的：</p><ul><li><strong>提供服务与功能</strong>：确保软件正常运行，例如检查更新、获取公告等。</li><li><strong>改进与优化</strong>：统计软件使用人数及版本分布，分析用户需求，优化产品性能与用户体验。</li></ul><h2 id="_3-信息共享与披露" tabindex="-1">3. 信息共享与披露 <a class="header-anchor" href="#_3-信息共享与披露" aria-label="Permalink to “3. 信息共享与披露”">​</a></h2><p>我们<strong>承诺不会出售、出租或交换</strong>您的任何信息。仅在法律要求或为履行法定义务所必需时，我们可能在合法范围内配合有权机关的要求披露相关信息。</p><h2 id="_4-数据跨境传输" tabindex="-1">4. 数据跨境传输 <a class="header-anchor" href="#_4-数据跨境传输" aria-label="Permalink to “4. 数据跨境传输”">​</a></h2><p>鉴于我们的 API 服务器位于境外，您使用软件时发出的请求将涉及数据跨境传输。我们已采取必要的技术措施（如 HTTPS 加密）确保传输过程的安全性，并选择符合行业标准的境外服务提供商。</p><h2 id="_5-数据安全保护" tabindex="-1">5. 数据安全保护 <a class="header-anchor" href="#_5-数据安全保护" aria-label="Permalink to “5. 数据安全保护”">​</a></h2><p>我们采用 HTTPS 加密协议等技术手段保护数据传输过程中的安全，防止信息被未经授权地访问、泄露、篡改或毁损。但请注意，尽管我们竭尽全力保护您的信息安全，任何互联网传输方式都无法保证绝对安全。</p><h2 id="_6-用户权利" tabindex="-1">6. 用户权利 <a class="header-anchor" href="#_6-用户权利" aria-label="Permalink to “6. 用户权利”">​</a></h2><p>根据适用法律法规，您有权知悉您的信息如何处理。由于我们不收集可直接识别个人的信息，因此无法提供特定个人的数据副本或删除特定数据。如您对本隐私政策或数据处理有任何疑问，可通过第 9 条列明的方式联系我们。</p><h2 id="_7-第三方链接" tabindex="-1">7. 第三方链接 <a class="header-anchor" href="#_7-第三方链接" aria-label="Permalink to “7. 第三方链接”">​</a></h2><p>我们的网站或软件可能包含指向第三方网站或服务的链接（例如 GitHub）。点击该等链接将离开我们的服务范围，我们对第三方的隐私实践不承担任何责任，建议您查阅其隐私政策。</p><h2 id="_8-隐私政策的更新" tabindex="-1">8. 隐私政策的更新 <a class="header-anchor" href="#_8-隐私政策的更新" aria-label="Permalink to “8. 隐私政策的更新”">​</a></h2><p>我们可能不时修订本隐私政策，以反映业务实践或法律法规的变化。更新后的隐私政策将在本页面公布，并注明生效日期。我们建议您定期查阅本页面以获取最新信息。重大变更我们可能通过网站公告或软件内通知等方式另行告知。</p><h2 id="_9-联系我们" tabindex="-1">9. 联系我们 <a class="header-anchor" href="#_9-联系我们" aria-label="Permalink to “9. 联系我们”">​</a></h2><p>如您对本隐私政策有任何疑问、意见或建议，欢迎通过以下方式联系我们：</p><ul><li>电子邮箱：<code>org@ceciliastudio.top</code> 或 <code>yizhimcqiu@icloud.com</code></li></ul><p>我们将尽快审核所涉问题，并在合理期限内予以回复。</p>',25)])])}const b=e(o,[["render",l]]);export{_ as __pageData,b as default};
